calc2('leap-year-checker', 'Leap Year Checker', 'calendar-check', 'Check whether a year is a leap year.', ['Year'], y => !Number.isInteger(y) || y < 1 ? 'Enter a valid year.' : `${y} is ${isLeap(y) ? '' : 'not '}a leap year (${isLeap(y) ? 366 : 365} days).`, ['2028']);
